//! Emoji: `:smile:` as you type, and a `:` suggestion.
//!
//! The emoji and shortcodes come from GitHub's gemoji, MIT licensed (see
//! `gemoji-license.txt`), generated by `scripts/emoji.ts`.

use std::sync::OnceLock;

use canvist_core::Binding;
use canvist_core::Command;
use canvist_core::CommandResult;
use canvist_core::CommandSpec;
use canvist_core::EditKind;
use canvist_core::EditorError;
use canvist_core::EditorState;
use canvist_core::Extension;
use canvist_core::Field;
use canvist_core::InputRule;
use canvist_core::NodeKind;
use canvist_core::NodeMeta;
use canvist_core::Platform;
use canvist_core::QuerySpec;
use canvist_core::Registration;
use canvist_core::RuleMatch;
use canvist_core::TypedExtension;
use canvist_core::ValueType;
use canvist_core::command;
use canvist_core::commands;
use canvist_extension_suggestion::Trigger;
use canvist_model::Attrs;
use canvist_model::Embed;
use canvist_model::EmbedSpec;
use canvist_model::EmbedTypeId;
use canvist_model::InlineText;
use canvist_model::Point;
use canvist_model::Schema;
use canvist_model::SchemaBuilder;
use canvist_model::Selection;
use canvist_model::Step;
use canvist_model::Value;

/// The embed's name, as in TipTap.
const EMOJI: &str = "emoji";

/// Every emoji: the character, a tab, and its shortcodes.
#[cfg(feature = "data")]
#[allow(
	clippy::unnecessary_wraps,
	reason = "matches the loaded table, which may be missing"
)]
fn table() -> Option<&'static str> {
	Some(include_str!("gemoji.txt"))
}

/// The table [`load`] was given.
#[cfg(not(feature = "data"))]
static LOADED: OnceLock<String> = OnceLock::new();

#[cfg(not(feature = "data"))]
fn table() -> Option<&'static str> {
	LOADED.get().map(String::as_str)
}

/// Give the extension its table, the text of `gemoji.txt`: one emoji per
/// line, a tab, and its space-separated shortcodes. Without the
/// `data` feature the table is not compiled in, so a binding can
/// load it as data on first use; until then no shortcode is known.
/// Returns whether this call loaded it, `false` once a table is loaded.
#[cfg(not(feature = "data"))]
pub fn load(table: String) -> bool {
	LOADED.set(table).is_ok()
}

/// With the `data` feature the table is compiled in, so there is
/// nothing to load: this keeps `load` callable in every build, and returns
/// `false`, as it does once a table is loaded.
#[cfg(feature = "data")]
#[must_use]
pub fn load(_table: String) -> bool {
	false
}

/// Whether the table is available: compiled in, or given to `load`.
#[must_use]
pub fn is_loaded() -> bool {
	table().is_some()
}

/// How many matches `searchEmoji` returns unless asked for more.
const DEFAULT_LIMIT: i64 = 10;

const TRIGGER: Trigger = Trigger {
	name: EMOJI,
	char: ':',
	allow_spaces: false,
};

/// One shortcode and its emoji.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EmojiItem {
	/// The shortcode, such as `smile`.
	pub name: &'static str,
	/// The emoji, such as `😄`.
	pub emoji: &'static str,
}

/// Every shortcode, sorted, parsed from the table on first use. Empty
/// while no table is loaded.
fn items() -> &'static [EmojiItem] {
	static ITEMS: OnceLock<Vec<EmojiItem>> = OnceLock::new();

	let Some(table) = table() else {
		return &[];
	};

	ITEMS.get_or_init(|| {
		let mut items: Vec<EmojiItem> = table
			.lines()
			.filter_map(|line| line.split_once('\t'))
			.flat_map(|(emoji, names)| names.split(' ').map(move |name| EmojiItem { name, emoji }))
			.collect();
		items.sort_unstable_by_key(|item| item.name);
		items
	})
}

/// The emoji for a shortcode, such as `smile`.
#[must_use]
pub fn lookup(name: &str) -> Option<&'static str> {
	find(name).map(|item| item.emoji)
}

/// The table's entry for a shortcode.
fn find(name: &str) -> Option<EmojiItem> {
	let items = items();
	let index = items.binary_search_by_key(&name, |item| item.name).ok()?;
	Some(items[index])
}

/// Up to `limit` emoji whose shortcode contains `query`, those starting
/// with it first, each group in shortcode order.
#[must_use]
pub fn search(query: &str, limit: usize) -> Vec<EmojiItem> {
	let query = query.to_ascii_lowercase();
	let (starting, containing): (Vec<&EmojiItem>, Vec<&EmojiItem>) = items()
		.iter()
		.filter(|item| item.name.contains(query.as_str()))
		.partition(|item| item.name.starts_with(query.as_str()));

	starting
		.into_iter()
		.chain(containing)
		.take(limit)
		.copied()
		.collect()
}

/// TipTap's `emoji` node: an inline atom with the shortcode in `name`.
/// canvist also stores the character in `emoji`, so any canvas draws it
/// without the table; a TipTap document without it shows `:name:`.
///
/// Typing a known `:shortcode:` inserts the emoji. Typing `:` starts a
/// suggestion: `emojiSuggestion` reports the query, `searchEmoji` finds
/// matches, and `setEmoji` replaces `:query` with the pick. The table is
/// GitHub's gemoji: 1,870 emoji and their shortcodes.
#[derive(Clone, Copy, Debug, Default)]
pub struct Emoji;

/// Typed access to [`Emoji`].
#[derive(Clone, Copy, Debug)]
pub struct EmojiHandle {
	_registration: Registration,
}

#[allow(
	clippy::unused_self,
	reason = "handle methods require proof of registration"
)]
impl EmojiHandle {
	/// The query typed after `:`, if an emoji is being suggested.
	#[must_use]
	pub fn suggestion(self, state: &EditorState) -> Option<String> {
		TRIGGER.find(state).map(|found| found.query)
	}

	/// Replace the suggestion, or insert at the caret, with the emoji for
	/// shortcode `name`. Unknown shortcodes do nothing.
	#[must_use]
	pub fn set(self, name: &str) -> Command {
		set(name)
	}

	/// Stop suggesting until another `:` is typed.
	#[must_use]
	pub fn dismiss(self) -> Command {
		command(|state| TRIGGER.dismiss(state))
	}
}

fn embed(kind: EmojiKind, item: EmojiItem) -> Embed {
	Embed {
		kind: kind.0,
		attrs: Attrs::new()
			.with("name", item.name)
			.with("emoji", item.emoji),
	}
}

/// The emoji embed type, resolved for one schema.
#[derive(Clone, Copy, Debug)]
struct EmojiKind(EmbedTypeId);

fn set(name: &str) -> Command {
	let name = name.to_owned();

	command(move |state| {
		let Some(item) = find(&name) else {
			return Ok(None);
		};
		let kind = EmojiKind(canvist_core::embed_type(state.schema(), EMOJI, EMOJI)?);
		let marks = commands::active_marks(state);
		let found = TRIGGER.find(state);
		canvist_extension_suggestion::replace(
			state,
			found,
			InlineText::embed(embed(kind, item), marks),
		)
	})
}

/// Replace a typed `:shortcode:` with its emoji. Unknown shortcodes stay
/// text.
fn shortcode(state: &mut EditorState, found: &RuleMatch, kind: EmojiKind) -> CommandResult {
	let Some(item) = found.group(1).and_then(find) else {
		return Ok(None);
	};
	let start = found.start;
	let marks = commands::marks_at(state.doc(), Point::new(found.block, start));
	let content = InlineText::embed(embed(kind, item), marks);
	let end = Point::new(found.block, start + content.len());

	state.change(EditKind::InputRule, |tr| {
		tr.delete_text(found.block, start..found.caret)?;
		tr.step(Step::InsertInline {
			block: found.block,
			offset: start,
			content,
		})?;
		tr.set_selection(Selection::caret(end));
		Ok(true)
	})
}

fn search_value(query: &str, limit: i64) -> Value {
	let limit = usize::try_from(limit).unwrap_or(0);
	let items = search(query, limit).into_iter().map(|item| {
		Value::from(
			Attrs::new()
				.with("name", item.name)
				.with("emoji", item.emoji),
		)
	});
	Value::from(items.collect::<Vec<_>>())
}

impl Extension for Emoji {
	fn name(&self) -> &'static str {
		EMOJI
	}

	fn schema(&self, schema: SchemaBuilder) -> SchemaBuilder {
		let attrs = Attrs::new()
			.with("name", Value::Null)
			.with("emoji", Value::Null);
		schema.embed(EmbedSpec::new(EMOJI).attrs(attrs))
	}

	fn nodes(&self) -> Vec<NodeMeta> {
		let name = Field::optional(
			"name",
			ValueType::nullable(ValueType::String),
			Value::Null,
			"The shortcode, such as `smile`.",
		);
		let emoji = Field::optional(
			"emoji",
			ValueType::nullable(ValueType::String),
			Value::Null,
			"The emoji itself, so it draws without the table.",
		);
		vec![NodeMeta::new(NodeKind::Embed, EMOJI).attr(name).attr(emoji)]
	}

	fn commands(&self, _schema: &Schema) -> Result<Vec<CommandSpec>, EditorError> {
		let set_spec = CommandSpec::new(
			"setEmoji",
			"Replace the emoji suggestion, or insert at the caret, with the emoji for a shortcode.",
			|args| Ok(set(args.string("name")?)),
		)
		.arg(Field::required(
			"name",
			ValueType::String,
			"The shortcode, such as `smile`.",
		));

		Ok(vec![
			set_spec,
			CommandSpec::simple(
				"dismissEmojiSuggestion",
				"Stop suggesting emoji until another `:` is typed.",
				command(|state| TRIGGER.dismiss(state)),
			),
		])
	}

	fn queries(&self, _schema: &Schema) -> Result<Vec<QuerySpec>, EditorError> {
		let item = ValueType::Record(vec![
			Field::required("name", ValueType::String, "The shortcode."),
			Field::required("emoji", ValueType::String, "The emoji."),
		]);
		let search_spec = QuerySpec::new(
			"searchEmoji",
			"Emoji whose shortcode contains the query, those starting with it first.",
			ValueType::list(item),
			|_, args| Ok(search_value(args.string("query")?, args.int("limit")?)),
		)
		.arg(Field::required(
			"query",
			ValueType::String,
			"What to look for, such as `smi`.",
		))
		.arg(Field::optional(
			"limit",
			ValueType::Int,
			DEFAULT_LIMIT,
			"The most matches to return.",
		));

		Ok(vec![
			QuerySpec::new(
				"emojiSuggestion",
				"The trigger character and the query typed after it, while an emoji is suggested.",
				canvist_extension_suggestion::query_type(),
				|state, _| Ok(TRIGGER.query_value(state)),
			),
			search_spec,
		])
	}

	fn keymap(&self, _schema: &Schema, _platform: Platform) -> Result<Vec<Binding>, EditorError> {
		Ok(vec![("Escape", command(|state| TRIGGER.dismiss(state)))])
	}

	fn input_rules(&self, schema: &Schema) -> Result<Vec<InputRule>, EditorError> {
		let kind = EmojiKind(canvist_core::embed_type(schema, EMOJI, EMOJI)?);
		let rule = InputRule::new(r":([a-zA-Z0-9_+-]+):$", move |state, found| {
			shortcode(state, found, kind)
		})?;
		Ok(vec![rule])
	}
}

impl TypedExtension for Emoji {
	type Handle = EmojiHandle;

	fn handle(&self, registration: Registration) -> EmojiHandle {
		EmojiHandle {
			_registration: registration,
		}
	}
}

#[cfg(test)]
mod tests {
	use super::*;

	/// The table, loaded as a binding would when it is not compiled in.
	fn table_loaded() {
		#[cfg(not(feature = "data"))]
		load(include_str!("gemoji.txt").to_owned());
		assert!(is_loaded());
	}

	#[test]
	fn the_table_parses_and_looks_up_every_shortcode() {
		table_loaded();
		assert_eq!(lookup("smile"), Some("😄"));
		assert_eq!(lookup("+1"), Some("👍"));
		assert_eq!(lookup("thumbsup"), lookup("+1"), "aliases share an emoji");
		assert_eq!(lookup("not_an_emoji"), None);
		assert!(items().len() > 1_800);
	}

	#[test]
	fn search_puts_prefix_matches_first() {
		table_loaded();
		let found = search("smile", 3);

		assert_eq!(found[0].name, "smile");
		assert!(found.iter().all(|item| item.name.contains("smile")));
		assert_eq!(found.len(), 3);
	}
}
